def get_sleep_data(user_id, start_date, end_date, refresh=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0521000" if __import__("os").path.isdir("./environment_mix/0521000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Minimal request log best-effort: store call/latency/status
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    log_row = {
        "id": "req_" + uuid.uuid4().hex,
        "endpoint": "get_sleep_data",
        "timestamp": now,
        "user_id": user_id,
        "status": "unknown",
        "latency_ms": None
    }

    def _finish(payload, status):
        log_row["status"] = status
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row)
        _save("request_logs.json", logs)
        return payload

    # Validate inputs
    if not isinstance(user_id, str) or not re.match(r"^oura_usr_[0-9A-HJKMNP-TV-Z]{18,26}$", user_id):
        return _finish(_err("VALIDATION_ERROR", "Invalid user_id."), "error")
    if not isinstance(start_date, str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", start_date):
        return _finish(_err("VALIDATION_ERROR", "Invalid start_date; expected YYYY-MM-DD."), "error")
    if not isinstance(end_date, str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", end_date):
        return _finish(_err("VALIDATION_ERROR", "Invalid end_date; expected YYYY-MM-DD."), "error")
    if refresh is not None and not isinstance(refresh, bool):
        return _finish(_err("VALIDATION_ERROR", "Invalid refresh; expected boolean."), "error")
    try:
        sd = datetime.date.fromisoformat(start_date)
        ed = datetime.date.fromisoformat(end_date)
    except ValueError:
        return _finish(_err("VALIDATION_ERROR", "Invalid date value(s)."), "error")
    if sd > ed:
        return _finish(_err("VALIDATION_ERROR", "start_date must be <= end_date."), "error")

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    user = next((u for u in users if isinstance(u, dict) and u.get("id") == user_id), None)
    if not user:
        return _finish(_err("NOT_FOUND", "User not found."), "error")
    if user.get("status") != "active":
        return _finish(_err("UNAUTHORIZED", "User is not active."), "error")

    conns = _load("oura_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("user_id") == user_id and c.get("provider") == "oura"), None)
    if not conn:
        return _finish(_err("NOT_FOUND", "No stored Oura connection for this user."), "error")
    if conn.get("status") == "revoked":
        return _finish(_err("UNAUTHORIZED", "Oura connection revoked; re-auth required."), "error")
    if conn.get("status") not in ("active", "error"):
        return _finish(_err("UNAUTHORIZED", "No usable Oura connection."), "error")

    # Optional refresh: enqueue a sync run; we do not call upstream offline, so mark as failed and set connection error
    sync_runs = _load("sync_runs.json")
    if not isinstance(sync_runs, list):
        sync_runs = []

    def _new_id(prefix):
        return prefix + uuid.uuid4().hex

    if refresh:
        run_id = _new_id("sync_")
        run = {
            "id": run_id,
            "user_id": user_id,
            "connection_id": conn.get("id"),
            "data_type": "sleep",
            "start_day": start_date,
            "end_day": end_date,
            "trigger": "tool_call",
            "status": "queued",
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "records_upserted": 0,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now
        }
        sync_runs.append(run)
        _save("sync_runs.json", sync_runs)

        # queued -> running
        run["status"] = "running"
        run["started_at"] = now
        run["updated_at"] = now
        _save("sync_runs.json", sync_runs)

        # running -> failed (offline)
        run["status"] = "failed"
        run["http_status"] = 401
        run["error_code"] = "invalid_token"
        run["error_message"] = "Upstream sync unavailable/offline; token validation failed."
        run["finished_at"] = now
        run["updated_at"] = now
        _save("sync_runs.json", sync_runs)

        # Business rule: on 401/invalid token, set connection status='error'
        conn_idx = next((i for i, c in enumerate(conns) if isinstance(c, dict) and c.get("id") == conn.get("id")), None)
        if conn_idx is not None:
            conns[conn_idx]["status"] = "error" if conns[conn_idx].get("status") != "revoked" else "revoked"
            conns[conn_idx]["last_error_code"] = "invalid_token"
            conns[conn_idx]["last_error_at"] = now
            conns[conn_idx]["updated_at"] = now
            _save("oura_connections.json", conns)

    sleep = _load("sleep_daily.json")
    if not isinstance(sleep, list):
        sleep = []

    # Filter by range inclusive, ordered by day asc
    out = []
    for r in sleep:
        if not isinstance(r, dict):
            continue
        if r.get("user_id") != user_id:
            continue
        d = r.get("day")
        if not isinstance(d, str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", d):
            continue
        if start_date <= d <= end_date:
            out.append(r)
    out.sort(key=lambda x: x.get("day") or "")

    return _finish(
        {
            "data": out,
            "meta": {
                "user_id": user_id,
                "start_date": start_date,
                "end_date": end_date,
                "count": len(out)
            }
        },
        "ok"
    )

