def get_today_sleep_data(user_id, refresh=None, **_extra):
    import json, os, datetime, re, time, uuid
    try:
        from zoneinfo import ZoneInfo
    except Exception:
        ZoneInfo = None

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0521000" if __import__("os").path.isdir("./environment_mix/0521000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    log_row = {
        "id": "req_" + uuid.uuid4().hex,
        "endpoint": "get_today_sleep_data",
        "timestamp": now,
        "user_id": user_id,
        "status": "unknown",
        "latency_ms": None
    }

    def _finish(payload, status):
        log_row["status"] = status
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row)
        _save("request_logs.json", logs)
        return payload

    if not isinstance(user_id, str) or not re.match(r"^oura_usr_[0-9A-HJKMNP-TV-Z]{18,26}$", user_id):
        return _finish(_err("VALIDATION_ERROR", "Invalid user_id."), "error")
    if refresh is not None and not isinstance(refresh, bool):
        return _finish(_err("VALIDATION_ERROR", "Invalid refresh; expected boolean."), "error")

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    user = next((u for u in users if isinstance(u, dict) and u.get("id") == user_id), None)
    if not user:
        return _finish(_err("NOT_FOUND", "User not found."), "error")
    if user.get("status") != "active":
        return _finish(_err("UNAUTHORIZED", "User is not active."), "error")

    tzname = user.get("timezone")
    if not isinstance(tzname, str) or not tzname:
        return _finish(_err("VALIDATION_ERROR", "User timezone is invalid."), "error")

    # Compute today's local date using timezone
    if ZoneInfo is None:
        # Fallback: treat as UTC if zoneinfo unavailable
        today = datetime.datetime.utcnow().date()
    else:
        try:
            tz = ZoneInfo(tzname)
            today = datetime.datetime.now(tz=tz).date()
        except Exception:
            return _finish(_err("VALIDATION_ERROR", "Invalid IANA timezone for user.", timezone=tzname), "error")
    day = today.isoformat()

    conns = _load("oura_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("user_id") == user_id and c.get("provider") == "oura"), None)
    if not conn:
        return _finish(_err("NOT_FOUND", "No stored Oura connection for this user."), "error")
    if conn.get("status") == "revoked":
        return _finish(_err("UNAUTHORIZED", "Oura connection revoked; re-auth required."), "error")
    if conn.get("status") not in ("active", "error"):
        return _finish(_err("UNAUTHORIZED", "No usable Oura connection."), "error")

    sleep = _load("sleep_daily.json")
    if not isinstance(sleep, list):
        sleep = []
    row = next((r for r in sleep if isinstance(r, dict) and r.get("user_id") == user_id and r.get("day") == day), None)

    # Staleness rule: if newest cached row for today is older than 15 minutes, enqueue sync and attempt refresh.
    stale = True
    if row and isinstance(row.get("fetched_at"), str):
        try:
            # Accept either Z or naive iso
            fa = row["fetched_at"]
            if fa.endswith("Z"):
                fetched_dt = datetime.datetime.fromisoformat(fa[:-1]).replace(tzinfo=datetime.timezone.utc)
                now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
            else:
                fetched_dt = datetime.datetime.fromisoformat(fa)
                now_dt = datetime.datetime.utcnow()
            stale = (now_dt - fetched_dt).total_seconds() > 15 * 60
        except Exception:
            stale = True

    should_refresh = bool(refresh) or stale

    if should_refresh:
        sync_runs = _load("sync_runs.json")
        if not isinstance(sync_runs, list):
            sync_runs = []

        run_id = "sync_" + uuid.uuid4().hex
        run = {
            "id": run_id,
            "user_id": user_id,
            "connection_id": conn.get("id"),
            "data_type": "sleep",
            "start_day": day,
            "end_day": day,
            "trigger": "tool_call",
            "status": "queued",
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "records_upserted": 0,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now
        }
        sync_runs.append(run)
        _save("sync_runs.json", sync_runs)

        # queued -> running
        run["status"] = "running"
        run["started_at"] = now
        run["updated_at"] = now
        _save("sync_runs.json", sync_runs)

        # running -> failed (offline)
        run["status"] = "failed"
        run["http_status"] = 401
        run["error_code"] = "invalid_token"
        run["error_message"] = "Upstream sync unavailable/offline; token validation failed."
        run["finished_at"] = now
        run["updated_at"] = now
        _save("sync_runs.json", sync_runs)

        # Apply 401 rule to connection
        conn_idx = next((i for i, c in enumerate(conns) if isinstance(c, dict) and c.get("id") == conn.get("id")), None)
        if conn_idx is not None:
            conns[conn_idx]["status"] = "error" if conns[conn_idx].get("status") != "revoked" else "revoked"
            conns[conn_idx]["last_error_code"] = "invalid_token"
            conns[conn_idx]["last_error_at"] = now
            conns[conn_idx]["updated_at"] = now
            _save("oura_connections.json", conns)

        # Re-load cached row in case something external updated it
        sleep = _load("sleep_daily.json")
        if not isinstance(sleep, list):
            sleep = []
        row = next((r for r in sleep if isinstance(r, dict) and r.get("user_id") == user_id and r.get("day") == day), None)

    return _finish(
        {
            "data": row,
            "meta": {
                "user_id": user_id,
                "day": day,
                "has_data": bool(row)
            }
        },
        "ok"
    )

def get_today_resilience_data(user_id, refresh=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0521000" if __import__("os").path.isdir("./environment_mix/0521000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_ts = time.time()
    endpoint = "get_today_resilience_data"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _get_user(users, uid):
        for u in users:
            if u.get("id") == uid:
                return u
        return None

    def _resolve_active_connection(conns, uid):
        user_conns = [c for c in conns if c.get("user_id") == uid and c.get("provider") == "oura"]
        if not user_conns:
            return None, "no_connection"
        active = [c for c in user_conns if c.get("status") == "active"]
        if active:
            return active[0], None
        revoked = [c for c in user_conns if c.get("status") == "revoked"]
        if revoked:
            return revoked[0], "revoked"
        return user_conns[0], "error"

    def _record_log(status, credential_id=None, user_id_used=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "user_id": user_id_used,
            "status": status,
            "detail": detail,
            "latency_ms": int((time.time() - start_ts) * 1000),
            "created_at": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate_quota():
        cfg = _load("service_config.json")
        if isinstance(cfg, dict):
            rate = cfg.get("rate_limit_per_minute")
            quota = cfg.get("quota_per_day")
        else:
            rate = None
            quota = None
        if rate is None and quota is None:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        if rate is not None:
            try:
                rate_i = int(rate)
                if rate_i > 0:
                    window_start = now - datetime.timedelta(minutes=1)
                    cnt = 0
                    for r in logs:
                        ts = _parse_iso(r.get("created_at"))
                        if ts and ts >= window_start:
                            cnt += 1
                    if cnt >= rate_i:
                        return _err("RATE_LIMIT", "Rate limit exceeded.")
            except Exception:
                pass
        if quota is not None:
            try:
                quota_i = int(quota)
                if quota_i > 0:
                    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
                    cnt = 0
                    for r in logs:
                        ts = _parse_iso(r.get("created_at"))
                        if ts and ts >= day_start:
                            cnt += 1
                    if cnt >= quota_i:
                        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
            except Exception:
                pass
        return None

    if not isinstance(user_id, str) or not re.match(r"^oura_usr_[0-9A-HJKMNP-TV-Z]{18,26}$", user_id):
        e = _err("VALIDATION_ERROR", "Invalid user_id.", field="user_id")
        _record_log("error", user_id_used=user_id, detail=e["error"])
        return e
    if refresh is not None and not isinstance(refresh, bool):
        e = _err("VALIDATION_ERROR", "Invalid refresh; must be boolean.", field="refresh")
        _record_log("error", user_id_used=user_id, detail=e["error"])
        return e

    lim = _enforce_rate_quota()
    if lim:
        _record_log("error", user_id_used=user_id, detail=lim["error"])
        return lim

    users = _load("users.json")
    conns = _load("oura_connections.json")
    daily = _load("resilience_daily.json")
    runs = _load("sync_runs.json")

    if not isinstance(users, list) or not isinstance(conns, list) or not isinstance(daily, list) or not isinstance(runs, list):
        e = _err("CONFLICT", "Datastore corrupted.")
        _record_log("error", user_id_used=user_id, detail=e["error"])
        return e

    u = _get_user(users, user_id)
    if not u:
        e = _err("NOT_FOUND", "User not found.")
        _record_log("error", user_id_used=user_id, detail=e["error"])
        return e
    if u.get("status") != "active":
        e = _err("UNAUTHORIZED", "User is not active.", user_status=u.get("status"))
        _record_log("error", user_id_used=user_id, detail=e["error"])
        return e

    conn, conn_state = _resolve_active_connection(conns, user_id)
    if not conn:
        e = _err("NOT_FOUND", "No stored Oura connection for user.")
        _record_log("error", user_id_used=user_id, detail=e["error"])
        return e
    if conn_state == "revoked":
        e = _err("UNAUTHORIZED", "Oura connection revoked; re-auth required.", connection_status="revoked")
        _record_log("error", user_id_used=user_id, detail=e["error"])
        return e
    if conn.get("status") != "active":
        e = _err("UNAUTHORIZED", "Oura connection not active.", connection_status=conn.get("status"))
        _record_log("error", user_id_used=user_id, detail=e["error"])
        return e

    tzname = u.get("timezone")
    try:
        from zoneinfo import ZoneInfo
        tz = ZoneInfo(tzname)
    except Exception:
        e = _err("CONFLICT", "Invalid or unsupported user timezone.", timezone=tzname)
        _record_log("error", user_id_used=user_id, detail=e["error"])
        return e

    today = datetime.datetime.now(tz).date().isoformat()

    rec = None
    for r in daily:
        if r.get("user_id") == user_id and r.get("day") == today:
            rec = r
            break

    def _is_stale(r):
        if not r:
            return True
        fetched = _parse_iso(r.get("fetched_at"))
        if not fetched:
            return True
        age = (datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - fetched).total_seconds()
        return age > 15 * 60

    want_refresh = bool(refresh) or _is_stale(rec)

    if want_refresh:
        now_iso = _now_iso()
        run_id = "sync_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        run = {
            "id": run_id,
            "user_id": user_id,
            "connection_id": conn.get("id"),
            "data_type": "resilience",
            "start_day": today,
            "end_day": today,
            "trigger": "tool_call",
            "status": "queued",
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "records_upserted": 0,
            "started_at": None,
            "finished_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        if conn.get("user_id") != user_id:
            e = _err("VALIDATION_ERROR", "Connection does not belong to user.")
            _record_log("error", user_id_used=user_id, detail=e["error"])
            return e

        runs.append(run)
        _save("sync_runs.json", runs)

        run["status"] = "running"
        run["started_at"] = now_iso
        run["updated_at"] = now_iso
        _save("sync_runs.json", runs)

        token = conn.get("access_token")
        refresh_ok = bool(token and isinstance(token, str) and token.strip())

        if not refresh_ok:
            conn["status"] = "error"
            conn["last_error_code"] = "invalid_token"
            conn["last_error_at"] = now_iso
            conn["updated_at"] = now_iso
            _save("oura_connections.json", conns)

            run["status"] = "failed"
            run["http_status"] = 401
            run["error_code"] = "token_expired"
            run["error_message"] = "Upstream rejected token."
            run["finished_at"] = now_iso
            run["updated_at"] = now_iso
            _save("sync_runs.json", runs)
        else:
            run["status"] = "succeeded"
            run["http_status"] = 200
            run["finished_at"] = now_iso
            run["updated_at"] = now_iso
            _save("sync_runs.json", runs)

        daily = _load("resilience_daily.json")
        rec = None
        for r in (daily if isinstance(daily, list) else []):
            if r.get("user_id") == user_id and r.get("day") == today:
                rec = r
                break

    resp = {
        "user_id": user_id,
        "day": today,
        "data": rec,
        "refreshed": bool(want_refresh),
    }
    _record_log("ok", user_id_used=user_id)
    return resp

def get_current_identity(authorization, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0521000" if __import__("os").path.isdir("./environment_mix/0521000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_current_identity"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _append_log(status_s, credential_used=None, user_id_used=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": credential_used,
            "user_id": user_id_used,
            "status": status_s,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate_quota(user_id_for_limits):
        cfg = _load("service_config.json")
        rate = None
        quota = None
        if isinstance(cfg, dict):
            rate = cfg.get("rate_limit_per_minute")
            quota = cfg.get("quota_per_day")
        try:
            rate_i = int(rate) if rate is not None else None
        except (TypeError, ValueError):
            rate_i = None
        try:
            quota_i = int(quota) if quota is not None else None
        except (TypeError, ValueError):
            quota_i = None

        if (rate_i is None or rate_i <= 0) and (quota_i is None or quota_i <= 0):
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        minute_start = now - datetime.timedelta(minutes=1)
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

        if rate_i is not None and rate_i > 0:
            count = 0
            for r in logs:
                if user_id_for_limits is not None and r.get("user_id") != user_id_for_limits:
                    continue
                ts = _parse_iso(r.get("created_at"))
                if ts is None:
                    continue
                if ts >= minute_start:
                    count += 1
            if count >= rate_i:
                return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rate_i)

        if quota_i is not None and quota_i > 0:
            count = 0
            for r in logs:
                if user_id_for_limits is not None and r.get("user_id") != user_id_for_limits:
                    continue
                ts = _parse_iso(r.get("created_at"))
                if ts is None:
                    continue
                if ts >= day_start:
                    count += 1
            if count >= quota_i:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota_per_day=quota_i)

        return None

    # Accept either "Bearer <token>" or a bare token (audit requires relaxing strictness)
    if not isinstance(authorization, str) or len(authorization.strip()) == 0:
        e = _err("UNAUTHORIZED", "Missing authorization.")
        _append_log("error", detail=e["error"])
        return e
    auth = authorization.strip()
    token = auth
    if auth.lower().startswith("bearer "):
        token = auth.split(None, 1)[1].strip() if len(auth.split(None, 1)) == 2 else ""

    if token == "":
        e = _err("UNAUTHORIZED", "Invalid authorization token.")
        _append_log("error", detail=e["error"])
        return e

    users = _load("users.json")
    if not isinstance(users, list):
        users = []

    # Realistic resolution: the "token" in this offline server maps to either users.id or users.external_subject.
    # Search for a usable active user; do not prematurely fail by picking a non-active match if another usable exists.
    user = None
    for u in users:
        if u.get("id") == token or (u.get("external_subject") is not None and u.get("external_subject") == token):
            user = u
            if u.get("status") == "active":
                break

    if not user:
        e = _err("UNAUTHORIZED", "Invalid bearer token.")
        _append_log("error", detail=e["error"])
        return e

    # Enforce rate/quota (if configured). Use resolved user id.
    lim = _enforce_rate_quota(user.get("id"))
    if lim is not None:
        _append_log("error", user_id_used=user.get("id"), detail=lim["error"])
        return lim

    if user.get("status") != "active":
        e = _err("UNAUTHORIZED", "User is not active.", user_id=user.get("id"), status=user.get("status"))
        _append_log("error", user_id_used=user.get("id"), detail=e["error"])
        return e

    conns = _load("oura_connections.json")
    if not isinstance(conns, list):
        conns = []
    # Pick the best available connection for identity: active first, else any non-revoked for diagnostics
    active_conn = None
    any_conn = None
    for c in conns:
        if c.get("user_id") != user.get("id") or c.get("provider") != "oura":
            continue
        any_conn = any_conn or c
        if c.get("status") == "active":
            active_conn = c
            break

    scopes = []
    conn_status = None
    conn_id = None
    if active_conn:
        conn_status = active_conn.get("status")
        conn_id = active_conn.get("id")
        sc = active_conn.get("scope")
        if isinstance(sc, list):
            scopes = [s for s in sc if isinstance(s, str)]
    elif any_conn:
        conn_status = any_conn.get("status")
        conn_id = any_conn.get("id")
        sc = any_conn.get("scope")
        if isinstance(sc, list):
            scopes = [s for s in sc if isinstance(s, str)]

    resp = {
        "identity": {
            "user": {
                "id": user.get("id"),
                "external_subject": user.get("external_subject"),
                "email": user.get("email"),
                "timezone": user.get("timezone"),
                "status": user.get("status"),
                "created_at": user.get("created_at"),
                "updated_at": user.get("updated_at"),
            },
            "oura_connection": {
                "id": conn_id,
                "provider": "oura" if conn_id is not None else None,
                "status": conn_status,
                "scopes": scopes,
            },
        },
        "limits": {
            "rate_limit_per_minute": (_load("service_config.json").get("rate_limit_per_minute") if isinstance(_load("service_config.json"), dict) else None),
            "quota_per_day": (_load("service_config.json").get("quota_per_day") if isinstance(_load("service_config.json"), dict) else None),
        },
        "server_time": _now_iso(),
    }

    _append_log("ok", credential_used=token, user_id_used=user.get("id"))
    return resp

def create_user(external_subject, timezone, email=None, status=None, **_extra):
    import json, os, datetime, re, time, secrets, zoneinfo
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0521000" if __import__("os").path.isdir("./environment_mix/0521000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_user"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _append_log(status_s, user_id_used=None, detail=None):
        logs = _ensure_list(_load("request_logs.json"))
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": None,
            "user_id": user_id_used,
            "status": status_s,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(18))

    def _is_valid_email(s):
        if not isinstance(s, str):
            return False
        s = s.strip()
        if len(s) < 3 or len(s) > 320:
            return False
        return re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", s) is not None

    try:
        # Validate inputs per tool schema
        if not isinstance(external_subject, str) or not (1 <= len(external_subject) <= 256):
            e = _err("VALIDATION_ERROR", "external_subject must be a non-empty string with maxLength 256.", field="external_subject")
            _append_log("error", detail=e["error"])
            return e

        if not isinstance(timezone, str) or not (1 <= len(timezone) <= 64):
            e = _err("VALIDATION_ERROR", "timezone must be a non-empty string with maxLength 64.", field="timezone")
            _append_log("error", detail=e["error"])
            return e

        # Validate timezone is an IANA tz name if possible
        try:
            zoneinfo.ZoneInfo(timezone)
        except Exception:
            e = _err("VALIDATION_ERROR", "timezone must be a valid IANA timezone name.", field="timezone")
            _append_log("error", detail=e["error"])
            return e

        if email is not None:
            if not _is_valid_email(email):
                e = _err("VALIDATION_ERROR", "email must be a valid email address.", field="email")
                _append_log("error", detail=e["error"])
                return e
            email = email.strip()

        # Status rules: tool allows only 'active' (or omitted -> active)
        if status is None:
            status = "active"
        if status != "active":
            e = _err("VALIDATION_ERROR", "status must be 'active' at creation.", field="status")
            _append_log("error", detail=e["error"])
            return e

        users = _ensure_list(_load("users.json"))

        # Uniqueness constraints:
        # - unique(external_subject) where external_subject is not null
        # - unique(email) where email is not null
        for u in users:
            if u.get("external_subject") is not None and u.get("external_subject") == external_subject:
                e = _err(
                    "CONFLICT",
                    "external_subject already exists (constraint: unique(external_subject) where external_subject is not null).",
                    field="external_subject"
                )
                _append_log("error", detail=e["error"])
                return e
            if email is not None and u.get("email") is not None and u.get("email") == email:
                e = _err(
                    "CONFLICT",
                    "email already exists (constraint: unique(email) where email is not null).",
                    field="email"
                )
                _append_log("error", detail=e["error"])
                return e

        now = _now_iso()
        new_row = {
            "id": _gen_id("oura_usr_"),
            "external_subject": external_subject,
            "email": email,
            "timezone": timezone,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }

        users.append(new_row)
        _save("users.json", users)

        _append_log("ok", user_id_used=new_row["id"], detail={"created_user_id": new_row["id"]})
        return {"user": new_row}
    except (OSError, json.JSONDecodeError) as ex:
        e = _err("VALIDATION_ERROR", "Datastore error while creating user.", detail=str(ex))
        _append_log("error", detail=e["error"])
        return e

