    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _append_log(status_s, user_id_used=None, detail=None):
        logs = _ensure_list(_load("request_logs.json"))
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": None,
            "user_id": user_id_used,
            "status": status_s,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _is_valid_email(s):
        if not isinstance(s, str):
            return False
        s = s.strip()
        if len(s) < 3 or len(s) > 320:
            return False
        return re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", s) is not None

    def _transition_allowed(frm, to):
        transitions = {
            "active": ["disabled", "deleted"],
            "disabled": ["active", "deleted"],
            "deleted": [],
        }
        return to in transitions.get(frm, [])

    try:
        if not isinstance(user_id, str) or not re.match(r"^oura_usr_[0-9A-HJKMNP-TV-Z]{18,26}$", user_id):
            e = _err("VALIDATION_ERROR", "user_id must match ^oura_usr_[0-9A-HJKMNP-TV-Z]{18,26}$.", field="user_id")
            _append_log("error", detail=e["error"])
            return e

        if email is None and timezone is None and status is None:
            e = _err("VALIDATION_ERROR", "At least one of email, timezone, or status must be provided.")
            _append_log("error", user_id_used=user_id, detail=e["error"])
            return e

        if email is not None and not _is_valid_email(email):
            e = _err("VALIDATION_ERROR", "email must be a valid email address.", field="email")
            _append_log("error", user_id_used=user_id, detail=e["error"])
            return e

        if timezone is not None:
            if not isinstance(timezone, str) or not (1 <= len(timezone.strip()) <= 64):
                e = _err("VALIDATION_ERROR", "timezone must be a non-empty string with maxLength 64.", field="timezone")
                _append_log("error", user_id_used=user_id, detail=e["error"])
                return e

        if status is not None:
            if status not in ("active", "disabled", "deleted"):
                e = _err("VALIDATION_ERROR", "status must be one of: active, disabled, deleted.", field="status")
                _append_log("error", user_id_used=user_id, detail=e["error"])
                return e

        users = _load("users.json")
        if isinstance(users, dict) and isinstance(users.get("rows"), list):
            container = users
            rows = users["rows"]
        else:
            container = None
            rows = users if isinstance(users, list) else []

        idx = None
        for i, u in enumerate(rows):
            if isinstance(u, dict) and u.get("id") == user_id:
                idx = i
                break
        if idx is None:
            e = _err("NOT_FOUND", "User not found.", user_id=user_id)
            _append_log("error", user_id_used=user_id, detail=e["error"])
            return e

        u = rows[idx]
        current_status = u.get("status")

        # uniqueness checks (ignore self; allow duplicates only if the other is deleted)
        if email is not None:
            email_norm = email.strip().lower()
            for other in rows:
                if not isinstance(other, dict):
                    continue
                if other.get("id") == user_id:
                    continue
                if other.get("email") and str(other.get("email")).strip().lower() == email_norm and other.get("status") != "deleted":
                    e = _err("CONFLICT", "email already exists for a non-deleted user (constraint: unique(email) where not null).", field="email")
                    _append_log("error", user_id_used=user_id, detail=e["error"])
                    return e

        if timezone is not None:
            u["timezone"] = timezone.strip()

        if email is not None:
            u["email"] = email.strip().lower()

        if status is not None and status != current_status:
            if not _transition_allowed(current_status, status):
                e = _err("INVALID_TRANSITION", f"Illegal status transition {current_status!r} -> {status!r}.", field="status")
                _append_log("error", user_id_used=user_id, detail=e["error"])
                return e
            u["status"] = status

        u["updated_at"] = _now_iso()
        rows[idx] = u

        if container is not None:
            container["rows"] = rows
            _save("users.json", container)
        else:
            _save("users.json", rows)

        _append_log("ok", user_id_used=user_id, detail={"updated": True})
        return {"user": u}
    except (TypeError, ValueError) as ex:
        e = _err("VALIDATION_ERROR", "Invalid input.", detail=str(ex))
        _append_log("error", user_id_used=user_id if isinstance(user_id, str) else None, detail=e["error"])
        return e

def revoke_oura_connection(user_id, provider, reason=None, **_extra):
    import json, os, datetime, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0521000" if __import__("os").path.isdir("./environment_mix/0521000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.utcnow()
    now = started.replace(microsecond=0).isoformat() + "Z"

    if not isinstance(user_id, str) or not re.match(r"^oura_usr_[0-9A-HJKMNP-TV-Z]{18,26}$", user_id):
        return _err("VALIDATION_ERROR", "Invalid user_id.", field="user_id")
    if provider != "oura":
        return _err("VALIDATION_ERROR", "Invalid provider.", field="provider")
    if reason is not None and reason not in ("user_request", "reauth_required", "security", "other"):
        return _err("VALIDATION_ERROR", "Invalid reason.", field="reason")

    users = _load("users.json")
    u = next((r for r in users if r.get("id") == user_id), None)
    if not u:
        return _err("NOT_FOUND", "User not found.", user_id=user_id)
    if u.get("status") != "active":
        return _err("UNAUTHORIZED", "User is not active.", user_id=user_id, status=u.get("status"))

    conns = _load("oura_connections.json")
    c = next((r for r in conns if r.get("user_id") == user_id and r.get("provider") == "oura"), None)
    if not c:
        return _err("NOT_FOUND", "No Oura connection found for user.", user_id=user_id)

    if c.get("status") == "revoked":
        return _err("INVALID_TRANSITION", "Connection is already revoked.", connection_id=c.get("id"))

    transitions = {"active": ["error", "revoked"], "error": ["active", "revoked"], "revoked": []}
    cur = c.get("status")
    if "revoked" not in transitions.get(cur, []):
        return _err("INVALID_TRANSITION", "Cannot revoke connection from current status.",
                    from_status=cur, to_status="revoked", connection_id=c.get("id"))

    c["status"] = "revoked"
    c["updated_at"] = now
    # optionally record reason in last_error_code for observability (schema doesn't have reason field)
    if reason:
        c["last_error_code"] = "revoked:" + reason
        c["last_error_at"] = now

    _save("oura_connections.json", conns)
    latency_ms = int((datetime.datetime.utcnow() - started).total_seconds() * 1000)
    return {"connection": c, "meta": {"latency_ms": latency_ms}}
